public static String convertToOppositeDirection(String attr) {
    if (attr.contains("Start") || attr.contains("End")) {
        return attr.replace("Start", "\u0000").replace("End", "Start").replace("\u0000", "End");
    } else if (attr.contains("Left") || attr.contains("Right")) {
        return attr.replace("Left", "\u0000").replace("Right", "Left").replace("\u0000", "Right");
    }
    return attr;
}

