public static int getFolderVersion(@NonNull File file) {
    int version = getVersionFromName(file.getName());
    if (version != -1) {
        return version;
    }
    File parent = file.getParentFile();
    if (parent != null) {
        version = getVersionFromName(parent.getName());
        if (version != -1) {
            return version;
        }
    }
    return -1;
}

private static int getVersionFromName(String name) {
    int index = name.indexOf("-v");
    while (index != -1) {
        int start = index + 2;
        int end = start;
        while (end < name.length() && Character.isDigit(name.charAt(end))) {
            end++;
        }
        if (end > start) {
            try {
                return Integer.parseInt(name.substring(start, end));
            } catch (NumberFormatException ignored) {
            }
        }
        index = name.indexOf("-v", index + 1);
    }
    return -1;
}

